#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

int counter = 0;

void setup() {
  Serial.begin(115200);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("Display nicht gefunden!");
    while (true);
  }
  display.clearDisplay();
  display.display();
}

void loop() {
  display.clearDisplay();

  // Grosser Text oben
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(2);
  display.setCursor(0, 0);
  display.println("MicroLearn");

  // Kleiner Zähler darunter
  display.setTextSize(1);
  display.setCursor(0, 20);
  display.print("count: ");
  display.println(counter++);

  // Smiley: Gesicht
  display.drawCircle(100, 40, 14, SSD1306_WHITE);
  // Augen
  display.fillCircle(95, 36, 2, SSD1306_WHITE);
  display.fillCircle(105, 36, 2, SSD1306_WHITE);
  // Mund
  display.drawLine(94, 46, 106, 46, SSD1306_WHITE);

  display.display();
  delay(500);
}
